\label{tab:factorial}
\begin{tabular}{lccc}
\toprule
 & Gradient ON & Gradient OFF & $\Delta$(ON$-$OFF) \\
\midrule
BatchNorm    & Full OCC (0.725) & Detach OCC (0.767) & $-$4.2 \\
LayerNorm    & Full OCC+LN (0.773) & Detach+LN (0.802) & $-$2.9 \\
\midrule
$\Delta$(BN$-$LN) & $-$4.8 ($d{=}{-}1.05$) & $-$3.5 ($d{=}{-}1.47$) & --- \\
